insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('access.data_class_reason.missing', 'access.data_class_reason', 'the reason is stored on the registry row so the next reader knows why this class and not the neighbouring one; it is a field, not a gate, and carries no character floor', NULL, 'Say in one line why these rows carry this class.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('access.data_class.forbidden_for_detail', 'access.data_class', 'a detail row''s access IS its parent''s; the live CHECK entity_types_class_scope_ck requires data_class and default_list_scope both NULL for the component variant', NULL, 'Remove access.data_class and access.default_list_scope; declare parents instead.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('access.data_class.ledger_private', 'access.data_class', 'a ledger''s lanes are read off its class (DD-174, iam.class_lanes): `private` has no organization-member lane, and the ledger generator refuses to emit against it', 'confidential | organization | public', 'If these rows belong to one person rather than to the organization, the type is `entity` with access.key_column = ''user_id''.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('access.data_class.missing', 'access.data_class', 'the class decides the RLS lane set (iam.class_lanes); an unset class resolves to `private`, which is a decision nobody made', 'private | confidential | organization | public', 'Set access.data_class and access.data_class_reason. platform.provision_options(''vocabularies'') lists the four.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('access.data_class.personal_not_private', 'access.data_class', 'access.key_column = ''user_id'' maps to the live `personal` variant, whose CHECK entity_types_personal_is_private_ck admits only a NULL or `private` class', 'private (or omit it)', 'Use access.data_class = ''private'', or drop key_column = ''user_id'' if these rows are not one person''s.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('access.default_list_scope.forbidden', 'access.default_list_scope', 'the live CHECK entity_types_class_scope_ck requires default_list_scope to be NULL for the component and ledger variants — a detail lists through its parent and a ledger is not listed', NULL, 'Remove access.default_list_scope.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('access.default_list_scope.missing', 'access.default_list_scope', 'a list of these rows has to default to something, and the default is never guessed', 'mine | organization', 'Set access.default_list_scope.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('access.key_column.missing', 'access.key_column', 'an entity is keyed either on created_by (the platform default) or on user_id (the personal shape), and the two produce different RLS', 'created_by | user_id', 'Set access.key_column = ''created_by'' unless these rows are one person''s own.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('access.key_column.user_id_missing', 'fields', 'access.key_column = ''user_id'' is the personal shape: every row is keyed on the one person in user_id, and iam.verify_canonical fails a personal table without that column', NULL, 'Declare a field {"name": "user_id", "type": "uuid", "not_null": true, "references": {"target": "auth.users", "on_delete": "cascade"}}.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('access.missing', 'access', 'the access block is the one block with NO silent defaults: who may read these rows is never guessed', NULL, 'Supply access with at least data_class and data_class_reason; the other members depend on the type.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('access.visibility.forbidden', 'access.visibility', 'a detail row''s visibility is its parent''s, and a restricted table has no visibility lane at all (the live builder requires it absent)', NULL, 'Remove access.visibility. The old ''none'' is expressed by NOT passing the field.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('access.visibility.reason_missing', 'access.visibility_reason', 'visibility = ''personal'' says these rows are somebody''s personal artifact, which is a claim about the data and not a default (db-rules §6a-1)', NULL, 'Add access.visibility_reason naming the personal artifact these rows are.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('access.visibility.required', 'access.visibility', 'a reference table is readable across the platform, so which visibility its rows are born with is part of its definition', 'personal | internal | link | public', 'Set access.visibility.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('association_types.unknown_token', 'association_types[].source_type', 'both ends of an association type must be registered tokens', NULL, 'Name registered tokens, or declare the association after both tables exist.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('association_types.wildcard_reason', 'association_types[].label', 'platform.enforce_known_association matches `r.label IS NULL OR r.label = NEW.label`, so a null label registers a WILDCARD for the whole type pair, not an unlabelled edge (lessons ledger 9)', NULL, 'Give the edge label, or say in notes why every label between these two types is allowed.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('certify.refused', '(certification)', 'iam.canonical_certify is the platform''s verdict on whether a table is canonical, and provision() refuses to commit a table its own verifier fails', NULL, 'The failing checks are listed in the finding. Fix the declaration and call provision again — nothing was written.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('doors.proof_failed', 'functions[].client_access', 'provision() closes with the proof (PLAN §4.5): for every declared door, the privileges that actually exist at the end of the transaction match the declaration — authenticated true and anon false for a signed-in door, both false for a server-only one', NULL, 'This is a provisioner or guard defect, not a spec defect: report the function named and the privileges observed.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('evolve.changed_spec', 'token', 'this token already carries a declaration and the one you passed differs; provision() creates, it never alters, because ADD COLUMN, a class change (DD-219 ordering) and a door change are each a different transaction shape', NULL, 'Call platform.evolve with the changed declaration once it ships (PLAN §3.1). Until then an existing token is changed by a migration with a named owner.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('fields.generated.stored', 'fields[].generated.stored', 'PostgreSQL only supports STORED generated columns; a virtual one silently is not what was declared', 'true', 'Set stored = true, or compute the value in a view instead.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('fields.name.base_collision', 'fields[].name', 'this name collides with a base column the builder always emits (id, organization_id, created_by, updated_by, created_at, updated_at, deleted_at, version, metadata, visibility, category_id)', NULL, 'Rename the column; the base column already carries this meaning.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('fields.name.duplicate', 'fields[].name', 'two fields declare the same column name, so one of them would be silently lost', NULL, 'Remove or rename the duplicate.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('fields.name.invalid', 'fields[].name', 'every spec-supplied identifier is emitted through quote_ident and must be a plain lower snake_case name', 'matching ^[a-z][a-z0-9_]{0,58}$', 'Rename the column.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('fields.references.on_delete.missing', 'fields[].references.on_delete', 'what happens to this row when its target disappears is a decision with four different consequences and no safe default', 'cascade | restrict | set_null | no_action', 'Set on_delete. `cascade` for a row that cannot outlive its parent, `restrict` to refuse the parent''s deletion.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('fields.references.target.unknown', 'fields[].references.target', 'the FK target must be an existing schema-qualified relation or a registered token', NULL, 'Name schema.table, or a registered token.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('fields.relationship_kind.association', 'fields[].relationship_kind', 'this FK pattern is an anything-to-anything edge, and a new junction table is a bug — the canonical edge store is platform.associations (assoc_link)', NULL, 'Remove the FK and write the edge with assoc_link, or say why this is genuinely a composition.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('fields.relationship_kind.missing', 'fields[].relationship_kind', 'THE FK-JUSTIFICATION LAW (2026-08-27): every FK says what KIND of edge it is, and `composition` is machine-verified against platform.entity_relationships rather than argued in prose', 'composition | reference | lookup', 'Set relationship_kind and a one-line note.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('fields.type.missing', 'fields[].type', 'a column needs a type; the provisioner never infers one from the name', NULL, 'Give the SQL type, e.g. text, uuid, jsonb, timestamptz, integer.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('functions.arg_checks.missing', 'functions[].arg_checks', 'a door is declared per ARGUMENT, not per function (lessons ledger 23): seo.map_diagnostics checked the map and not the p_site_id it also took, and read another tenant''s web.page through a door whose prose reason was true and insufficient', NULL, 'Add an arg_checks entry for every entity-id argument, including ids nested inside a jsonb argument by path (e.g. filters.site_id).') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('functions.arg_checks.null_rule_missing', 'functions[].arg_checks.<arg>.null_rule', 'NULL is an argument (lessons ledger 27): an optional entity id''s default branch is its own code path, and seo.map_diagnostics answered p_site_id => NULL by reading every bound site — a door that promises a check on the id promises nothing about the NULL branch unless it is declared', NULL, 'Declare arg_checks.<arg> = {"check": "...", "null_rule": "NULL means ... and is limited to what the caller can view"}, or make the argument required.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('functions.body.missing', 'functions[].body', 'provision() creates the function, so it needs the source; without it there is nothing to create', NULL, 'Supply body. This field is lane A only — a lane-B caller declares doors for functions that already exist.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('functions.client_access.missing', 'functions[].client_access', 'whether a browser session may call this function is the access decision, and §6d-4 refuses an undeclared client grant at grant time — there is no default', 'anonymous | signed_in | server_only', 'Declare client_access and the reason that becomes the door row.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('functions.door_exists', 'functions[].name', 'this function already has a platform.client_callable_door row, and provision() creates doors, it never rewrites one', NULL, 'Change an existing door with a migration that names its owner, or with platform.evolve once it ships.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('functions.non_client_lane.missing', 'functions[].non_client_lane', 'client_access = server_only says no browser session reaches this function, so the row must name the lane that DOES reach it; the live CHECK door_non_client_lane_is_declared requires at least 40 characters of it', NULL, 'Name the server lane or role that calls it, in a sentence.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('functions.not_found', 'functions[].name', 'an entry with no body declares a door for a function that already exists in this spec''s schema, and there is none by that name; a door for nothing would be a grant waiting for a function', NULL, 'Name an existing function in the declared schema, or (lane A only) supply the body so provision() creates it.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('functions.reason.missing', 'functions[].reason', 'the reason becomes platform.client_callable_door.reason, which is what an auditor reads to decide whether this door should exist', NULL, 'Say who calls it and what it gives them.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('identity.description.missing', 'description', 'the description becomes COMMENT ON TABLE — the cheapest machine-readable statement of intent we have, free inside the transaction, and the first thing an outside agent reads', NULL, 'Say in one or two sentences what one row of this table IS.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('identity.label.missing', 'label', 'the label is what a person sees in every picker and share dialog; there is no defaulting a human-readable name from a snake_case token without producing nonsense', NULL, 'Give the human-readable singular name, e.g. "Topical map".') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('identity.same_role_as.unknown', 'same_role_as.token', 'same_role_as must name a token that is actually registered, or the claim that the two tables share a role cannot be checked by anyone', NULL, 'Name the registered token of the colliding table, or rename this table instead.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('identity.schema.forbidden', 'schema', 'public, graveyard, pg_*, information_schema and the Supabase-managed schemas are not feature schemas; Doctrine §7 keeps functions and RPCs in public and never tables, and platform._ddl_guard lane (g) refuses a new table there outright', NULL, 'Name the FEATURE schema these rows belong to. Call platform.provision_options(''schemas'') for the list.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('identity.schema.missing', 'schema', 'every table belongs to a feature schema; nothing is created without one being named', NULL, 'Call platform.provision_options(''schemas'') for the schemas you may declare into.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('identity.schema.not_generable', 'schema', 'the repository cannot generate code for this schema, so the table would exist in the database and be invisible to every ORM model, TypeScript type and client registry the platform reads — platform.provision_generate_target is the repo''s own generate list, pushed into the database by scripts/check_provision_generate_targets.py', NULL, 'Add the schema to BOTH generate lists and re-run: aidream db/matrx_orm.yaml (databases[0].additional_schemas) and matrx-frontend package.json "db-types" (add --schema <name>). Then publish the list into the database with `uv run python scripts/check_provision_generate_targets.py --fix` in aidream, commit both repositories, and call platform.provision again. Or name a schema that is already a target — platform.provision_options(''schemas'') lists exactly those.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('identity.schema.unknown', 'schema', 'the named schema does not exist in this database, and provision() never creates a schema — a new schema needs a person, because matrx-frontend package.json''s db-types --schema list is hand-maintained and a schema missing from it is invisible to the frontend forever', NULL, 'Call platform.provision_options(''schemas'') for the legal list, or ask an operator to create the schema and add it to the frontend type generation list first.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('identity.table.collision', 'table', 'this table name already exists in another schema, and a repeated table name must mean the same ROLE (db-rules §1a) — otherwise two unrelated things answer to one word and every reader after you pays for it', NULL, 'Either rename this table, or set same_role_as = {token, reason} naming the colliding token and saying in one sentence why these two genuinely share a role.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('identity.table.missing', 'table', 'the relation has to be named before anything can be built', NULL, 'Give a singular snake_case table name.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('identity.table.name', 'table', 'every spec-supplied identifier is emitted through quote_ident and must be a plain lower snake_case name of at most 59 characters, so no identifier can carry SQL', 'matching ^[a-z][a-z0-9_]{0,58}$', 'Rename to lower snake_case. Singular, not plural.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('identity.token.missing', 'token', 'the token is the platform''s name for this record type: pickers, shares, associations, knobs and the docs registry all resolve through it', NULL, 'Give a snake_case token, conventionally <feature>_<thing>.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('identity.token.taken', 'token', 'this token is already registered in platform.entity_types, and one token names exactly one relation', NULL, 'Pick a free token, or — if you meant to change the table this token already names — call platform.evolve instead of platform.provision.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('indexes.method.unknown', 'indexes[].method', 'the index method must be one PostgreSQL actually has installed here', 'btree | gin | gist | hnsw', 'Pick one, or omit method for btree.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('indexes.unique_soft_delete', 'indexes[].where', 'a unique index on a soft-deletable table without a deleted_at IS NULL predicate makes a deleted row block its own replacement forever (DD-121; check:soft-delete-unique is red in CI for exactly this)', 'where = "deleted_at IS NULL"', 'The provisioner adds the predicate for you. To ship without it, give indexes[].where_omitted_reason.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('knobs.json_range', 'knobs[].min_value', 'the live CHECK feature_knob_json_no_range_check forbids min_value, max_value and allowed_values on a json knob', NULL, 'Remove the range, or use a number/integer knob.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('knobs.overridable_by.unknown', 'knobs[].overridable_by', 'an override rung must be one of the 11 live platform.knob_scope_kind rows; a rung that does not exist silently never fires', NULL, 'Call platform.provision_options(''knob_rungs'') for the 11. An empty array means platform-locked.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('knobs.secret_shape', 'knobs[].value', 'the live CHECK feature_knob_secret_shape_check requires a secret knob''s value and default to be objects carrying vault_key, with min_value, max_value and allowed_values all NULL', NULL, 'Shape the value as {"vault_key": "..."} and drop any range.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('knobs.value_type.unknown', 'knobs[].value_type', 'the live CHECK feature_knob_value_type_check admits a closed list', NULL, 'Pick one. `secret` additionally requires an object value carrying vault_key.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('lane.default_menu', 'fields[].default', 'a free default expression is SQL text executed by a postgres-owned SECURITY DEFINER; the closed subset admits only a fixed menu', 'null | a literal of the column''s type | now() | gen_random_uuid() | auth.uid() | true | false | 0 | ''{}''::jsonb | ''[]''::jsonb', 'Pick from the menu, or ask a trusted operator to provision this table on lane A.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('lane.expression_refused', '(see the finding)', 'this field is raw SQL text that provision() would execute as a SECURITY DEFINER owned by postgres, so it is lane A only; the closed subset a non-trusted agent may speak has no expression field at all (PLAN §4.0, ATTACK-2 finding 1)', NULL, 'Remove the field. A lane-B declaration builds tables, columns, FKs, indexes by column list, registration, sharing, association types and knobs — and declares doors for functions that already exist.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('lane.org_missing', 'p_org_id', 'a lane-B call acts for exactly ONE organization, and that organization is resolved by the MCP tool from the OAuth identity and passed as a verified argument — never taken from the spec, which the caller controls', NULL, 'This is our MCP tool''s job, not the caller''s: it passes the verified organization. A direct SQL call to provision_restricted with no organization is refused.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('lane.schema_not_granted', 'schema', 'lane B may only declare into schemas its organization holds in platform.provision_grant, which ships empty so nothing is open until an operator opens it on purpose', NULL, 'Call platform.provision_options(''schemas'') to see which schemas your organization holds, or ask an operator for a platform.provision_grant row.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('origin.custom_unbuilt', 'origin', 'origin = custom needs the custom record store, which does not exist: the live platform.adopt_custom_fields writes a column named `custom` and a platform.custom_field_target row, which is not Doctrine R13''s ruled shape (custom_fields jsonb, definitions in custom.field). Raised on DD-020/DD-022', 'standard', 'Declare `standard`. A genuinely customer-defined record type waits for the custom record store.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('origin.missing', 'origin', 'Data Doctrine R2 names a PAIR — type and origin — and origin decides whether these rows live in the standard store or the custom record store', 'standard | custom', 'Use `standard` unless this is a customer-defined record type.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('parents.cross_tenant', 'parents', 'a detail inherits its parent''s read lane, so parenting onto a token another organization owns is a read-lane grab that an existence check does not stop (PLAN §4.0)', NULL, 'Parent onto a token your organization owns, or a `reference` token.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('parents.forbidden', 'parents', 'parents[] declares composition parents and is only meaningful for `detail`; any other type owns its own access', NULL, 'Remove parents, or change type to `detail`.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('parents.missing', 'parents', 'a detail table has no access of its own — it inherits its read lane from its parent, so a parentless detail is a table nobody can read or a table everybody can', NULL, 'Declare parents as ["parent_token:fk_column"], and declare that FK column in fields[].') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('parents.shape', 'parents', 'each entry names the parent token and the FK column on THIS table that points at it', NULL, 'Shape each entry as "parent_token:fk_column".') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('parents.unknown_column', 'parents', 'the FK column named must be one this spec actually declares in fields[]', NULL, 'Declare the FK column in fields[] with references.target pointing at the parent.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('parents.unknown_token', 'parents', 'the parent token must already be registered; a detail inherits the read lane of a token that does not exist is not a lane', NULL, 'Name a registered parent token. platform.provision_options(''tokens'') lists them.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('preflight.event_trigger', '(preflight)', 'the whole enforcement chain rests on 7 platform event triggers, and a database restore provably drops them; provisioning into a database whose guards are off writes objects nothing checked', NULL, 'Re-bind and enable the named event trigger, then call provision again. scripts/check_db_guards.py lists all seven.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('preflight.lock_timeout', '(preflight)', 'an unbounded lock_timeout lets one ACCESS EXCLUSIVE wait queue behind a long read and block every writer of that table for as long as the read runs', 'any bounded value, e.g. 5s', 'SET lock_timeout = ''5s'' and call provision again.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('preflight.marker', '(preflight)', 'the matrx.provisioner marker is already set on entry, which means this call is nested inside another provisioning run and the two would interleave their DDL', NULL, 'Finish or roll back the outer provisioning call first.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('preflight.read_kernel', '(preflight)', 'iam.entity_read_kernel_fingerprint() does not match iam.entity_read_kernel_expected(), which means the entity read kernel has drifted from the shape apply_rls was written against; provision() calls iam.apply_rls, so provisioning now would rewrite std_select into the unbounded per-row form on this new table', NULL, 'Do not provision until the kernel is reconciled (table-provisioning REGISTER P2-00f). Either restore the kernel functions or re-record the expected fingerprint in a migration that says what changed and why.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('preflight.session_replication_role', '(preflight)', 'session_replication_role = replica disables every ordinary trigger — _stamp_actor, _touch_row, enforce_known_association and the registry integrity triggers — so a table built in replica mode is built without them', 'origin', 'SET session_replication_role = ''origin'' and call provision again.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('registration.audit_class.reason_missing', 'audit_class_reason', 'the live CHECK entity_types_machinery_reason requires a written reason whenever audit_class is machinery — it is the only record of why this relation left the entity audit lane', NULL, 'Write the reason, or leave audit_class = ''entity''.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('registration.category_label.missing', 'category_label', 'the category label is how this token groups in every listing surface; 711 live tokens have none and each one is a listing that reads as ungrouped', NULL, 'Give the grouping label, e.g. "SEO".') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('registration.component_anon_read.missing', 'component_anon_read_via_public_parent', 'this decides whether ANONYMOUS readers reach these rows through a public parent, which is part of the access block and has no platform answer', 'true | false', 'Answer false unless these detail rows are meant to be readable by signed-out visitors of a public parent.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('registration.content_role.unknown', 'content_role', 'the live CHECK entity_types_content_role_check admits a closed list', NULL, 'Pick one, or omit content_role entirely.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('registration.relation_kind.projection', 'relation_kind', 'the live CHECK entity_types_projection_contract requires a projection to name projects_token AND to be machinery', NULL, 'Set projects_token, or declare relation_kind = ''table''.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('registration.taxonomy_node_id.missing', 'taxonomy_node_id', 'pickers, the docs registry and the feature registry all resolve through the taxonomy node; a token with no node is invisible to all three', NULL, 'Call platform.provision_options(''taxonomy'') for the live nodes and pick the one this table belongs to.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('registration.taxonomy_node_id.unknown', 'taxonomy_node_id', 'the node must exist in platform.taxonomy_node (the live FK entity_types_taxonomy_node_id_fkey enforces it anyway, with an error that names nothing)', NULL, 'Call platform.provision_options(''taxonomy'') for the live nodes.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('registration.title_column.missing', 'title_column', 'is_listed = true means a picker will show these rows, and a picker with no title column has nothing to show', NULL, 'Name the column holding the human-readable title, or set is_listed = false.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('registration.title_column.unknown', 'title_column', 'the title column must be a column this spec creates, or the picker resolves nothing', NULL, 'Name one of this table''s own columns.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('shape.invalid', '(see the finding)', 'the spec does not match the declaration''s JSON shape (platform.provision_schema), so the field named is the wrong type, is unknown, or is nested wrongly', NULL, 'Call platform.provision_options(''schema'') for the shape contract this spec is checked against, then fix the named path.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('sharing.excluded_and_public', 'sharing.public_columns', 'a column in both client_excluded_columns and public_columns cannot work: the frontend pipeline runs strip-client-excluded-columns.ts, so an excluded column DISAPPEARS from database.types.ts and the share renderer would reference a field the types say does not exist', NULL, 'Take the column out of one of the two lists.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('sharing.missing', 'sharing', 'whether these rows can be shared is a decision, and `false` is a legal answer that must be given rather than assumed', NULL, 'Set sharing = false, or give the sharing object.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('type.missing', 'type', 'the type decides the RLS lane set, so nothing about this table''s access can be resolved without it', NULL, 'Call platform.provision_options(''types'') for the seven and what each one means.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('type.not_provisionable', 'type', '`deprecated` is produced by platform.deprovision, never declared — a table is not born retired', NULL, 'Declare the type these rows actually are; retire an existing token with platform.deprovision.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('type.self_declared_machinery', 'type', 'marking a relation as machinery takes it out of the entity audit lane, and that is Arman''s decision with a written reason on the row (PLAN §4.2, §11) — the provisioner refuses to self-declare it', NULL, 'Declare the type these rows actually are. If this really is machinery, an operator sets audit_class after the fact with audit_class_reason.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('type.unknown', 'type', 'the Data Doctrine R2 vocabulary is a CLOSED seven; a word outside it has no mapping to a live rls_variant', NULL, 'Pick one of the seven. platform.provision_options(''types'') describes each.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('views.definition.missing', 'views[].definition', 'a view is its definition; there is nothing to create without it', NULL, 'Supply definition. This field is lane A only.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('views.projection.primary_key', 'views[].primary_key', 'a registered view with no declared primary key makes python db/generate.py hard-fail for EVERY schema, not just this one', NULL, 'Declare primary_key, or set registered_as_projection = false.') on conflict (rule_id) do nothing;
insert into platform.provision_rule_message (rule_id, field_path, why, legal_values, otherwise) values ('views.security_invoker.exemption', 'views[].security_invoker', 'a view without security_invoker = true reads with its OWNER''s privileges, which means it reads past RLS for every caller; 26 live non-Supabase views still carry that and each one is a standing leak', 'true', 'Set security_invoker = true, or give security_invoker_reason saying which caller genuinely needs the owner''s reach.') on conflict (rule_id) do nothing;
